// Sound effects. The WAV files in assets/sfx/ are generated by `npm run sfx` (scripts/sfx/generate.mjs).
// Each sound gets one player, created on first use and restarted on every play.
// Sounds mix with the user's music instead of pausing it, and stay quiet when the phone is on silent.
import { createAudioPlayer, setAudioModeAsync, type AudioPlayer } from 'expo-audio';

const SOURCES = {
  tap: require('../../assets/sfx/tap.wav'),
  tier1: require('../../assets/sfx/tier1.wav'),
  tier2: require('../../assets/sfx/tier2.wav'),
  tier3: require('../../assets/sfx/tier3.wav'),
  tier4: require('../../assets/sfx/tier4.wav'),
  flash: require('../../assets/sfx/flash.wav'),
  legendary: require('../../assets/sfx/legendary.wav'),
  arrive: require('../../assets/sfx/arrive.wav'),
  doors: require('../../assets/sfx/doors.wav'),
  pop: require('../../assets/sfx/pop.wav'),
  sparkle: require('../../assets/sfx/sparkle.wav'),
  stamp: require('../../assets/sfx/stamp.wav'),
  exp: require('../../assets/sfx/exp.wav'),
  levelup: require('../../assets/sfx/levelup.wav'),
  open: require('../../assets/sfx/open.wav'),
  locked: require('../../assets/sfx/locked.wav'),
  hop: require('../../assets/sfx/hop.wav'),
} as const;

export type SfxName = keyof typeof SOURCES;

/** The rarity-light step sounds, in order (common, rare, epic, legendary). */
export const TIER_SFX: readonly SfxName[] = ['tier1', 'tier2', 'tier3', 'tier4'];

const players: Partial<Record<SfxName, AudioPlayer>> = {};
let enabled = true;
let audioModeSet = false;

function setAudioModeOnce() {
  if (audioModeSet) return;
  audioModeSet = true;
  setAudioModeAsync({ playsInSilentMode: false, interruptionMode: 'mixWithOthers' }).catch(() => {});
}

function playerFor(name: SfxName): AudioPlayer | undefined {
  if (!players[name]) {
    try {
      players[name] = createAudioPlayer(SOURCES[name]);
    } catch {
      return undefined; // no audio on this device; stay silent
    }
  }
  return players[name];
}

/** Loads every sound so the first play has no delay. Safe to call more than once. */
export function preloadSfx() {
  setAudioModeOnce();
  for (const name of Object.keys(SOURCES) as SfxName[]) playerFor(name);
}

/** Plays a sound from the start. Never throws: on failure the game just stays silent. */
export function playSfx(name: SfxName) {
  if (!enabled) return;
  setAudioModeOnce();
  const player = playerFor(name);
  if (!player) return;
  try {
    if (player.currentTime > 0) {
      player
        .seekTo(0)
        .then(() => player.play())
        .catch(() => {});
    } else {
      player.play();
    }
  } catch {
    // ignore: sound is a nice-to-have
  }
}

export function setSfxEnabled(on: boolean) {
  enabled = on;
}

export function isSfxEnabled() {
  return enabled;
}
